def n_enc(a,bg,m):
    H,W=a.shape; seen=np.zeros_like(a,bool); cnt=0
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    for i,j in zip(*np.where(~seen & (a==bg))):
        st=[(int(i),int(j))]; comp=[]; touch=False; hasm=False
        while st:
            c=st.pop()
            if 0<=c[0]<H and 0<=c[1]<W and not seen[c]:
                seen[c]=True; comp.append(c)
                if c[0] in (0,H-1) or c[1] in (0,W-1): touch=True
                if a[c]==m: hasm=True
                for d in dirs: st.append((c[0]+d[0],c[1]+d[1]))
